size_t RegisterJPEGImage() {
    static const char *description = "JPEG image format";
    static const char *version = "JPEG library version 9.0";

    MagickInfo *magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(MagickInfo));
    if (magick_info == (MagickInfo *) NULL)
        return 0;

    (void) memset(magick_info, 0, sizeof(MagickInfo));
    magick_info->decoder = JPEGDecoder;
    magick_info->encoder = JPEGEcoder;
    magick_info->thread_support = MagickTrue;
    magick_info->mime_type = (char *) AcquireString("image/jpeg");
    magick_info->description = (char *) AcquireString(description);

    if (JPEGLibraryVersion() >= 90)
        magick_info->thread_support = MagickTrue;
    else
        magick_info->thread_support = MagickFalse;

    if (RegisterMagickInfo("JPE", magick_info) == MagickFalse) {
        magick_info = (MagickInfo *) RelinquishMagickMemory(magick_info);
        return 0;
    }

    if (RegisterMagickInfo("JPEG", magick_info) == MagickFalse) {
        magick_info = (MagickInfo *) RelinquishMagickMemory(magick_info);
        return 0;
    }

    if (RegisterMagickInfo("JPG", magick_info) == MagickFalse) {
        magick_info = (MagickInfo *) RelinquishMagickMemory(magick_info);
        return 0;
    }

    if (RegisterMagickInfo("JPS", magick_info) == MagickFalse) {
        magick_info = (MagickInfo *) RelinquishMagickMemory(magick_info);
        return 0;
    }

    if (RegisterMagickInfo("PJPEG", magick_info) == MagickFalse) {
        magick_info = (MagickInfo *) RelinquishMagickMemory(magick_info);
        return 0;
    }

    magick_info = (MagickInfo *) RelinquishMagickMemory(magick_info);

    return strlen(description) + 1 + strlen(version) + 1;
}
